<script lang="ts">import type { PageData } from './$types';let {data}:{data:PageData}=$props(); const orderLabels:Record<string,string>={new:'Новый',received:'Принят',payment_canceled:'Оплата отменена',submitted:'Передан менеджеру',pending_payment:'Ожидает оплаты',awaiting_payment:'Ожидает оплаты',payment_pending:'Ожидает оплаты',paid:'Оплачен',payment_review:'Нужна проверка оплаты',payment_failed:'Ошибка оплаты',cancelled:'Отменён'}; const paymentLabels:Record<string,string>={not_required:'Оплата с менеджером',not_requested:'Оплата с менеджером',pending:'Ожидает оплаты',creating:'Подготавливается',succeeded:'Оплачен',canceled:'Отменён',failed:'Ошибка',needs_review:'Нужна проверка',none:'Не выбрана',waiting_for_capture:'Ожидает подтверждения'};</script>
<svelte:head><title>Заказы и оплата — Орбита-строй</title></svelte:head>
<h1 class="text-3xl font-bold">Заказы и оплата</h1><p class="mt-2 text-muted">Сохранённые заказы и подтверждённые статусы оплаты.</p>{#if data.error}<p role="alert" class="notice notice-error mt-6">{data.error}</p>{/if}
<div class="mt-6 overflow-x-auto rounded border border-slate-200 bg-white"><table class="w-full text-left"><thead class="bg-slate-50"><tr><th class="p-4">Заказ</th><th class="p-4">Дата</th><th class="p-4">Товары, ₽</th><th class="p-4">Статус</th><th class="p-4">Оплата</th></tr></thead><tbody>{#each data.orders as order}<tr class="border-t border-slate-200"><td class="min-w-64 p-4"><span class="font-semibold">{order.id}</span>{#if order.customer}<details class="mt-3"><summary class="flex min-h-11 cursor-pointer items-center text-sm font-semibold text-brand">Состав и контакты</summary><div class="space-y-2 pt-2 text-sm"><p>{order.customer.name}</p><p>{order.customer.phone}</p>{#if order.customer.address}<p>{order.customer.address}</p>{/if}{#if order.customer.comments}<p>{order.customer.comments}</p>{/if}<ul>{#each order.items || [] as item}<li>{item.name}: {item.quantity} {item.unit}</li>{/each}</ul></div></details>{/if}</td><td class="whitespace-nowrap p-4">{new Date(order.createdAt).toLocaleString('ru-RU')}</td><td class="p-4 tabular-nums">{order.total}</td><td class="p-4">{orderLabels[order.status] || 'Уточняется'}</td><td class="p-4">{paymentLabels[order.paymentStatus || order.payment_status || 'none'] || 'Уточняется'}</td></tr>{:else}<tr><td class="p-8 text-center text-muted" colspan="5">{data.error ? 'Заказы недоступны' : 'Заказов пока нет.'}</td></tr>{/each}</tbody></table></div><nav aria-label="Страницы заказов" class="mt-6 flex justify-between">{#if data.page>1}<a class="button button-secondary" href={`/admin/orders?page=${data.page-1}`}>Назад</a>{:else}<span></span>{/if}{#if data.page<data.lastPage}<a class="button button-secondary" href={`/admin/orders?page=${data.page+1}`}>Далее</a>{/if}</nav>
